import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { verifyToken } from './jwt';
import { securityHeadersMiddleware } from './security-headers';

export function authMiddleware(request: NextRequest) {
  // Apply security headers
  let response = securityHeadersMiddleware(request);

  const token = request.cookies.get('next-auth.session-token')?.value ||
                request.headers.get('authorization')?.replace('Bearer ', '');

  if (!token) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401, headers: response.headers }
    );
  }

  try {
    const payload = verifyToken(token);
    // Add user info to request headers for downstream use
    // NOTE: Downstream code should verify these headers are set by trusted middleware
    // and never trust headers that could be set by the client
    const requestHeaders = new Headers(request.headers);
    requestHeaders.set('x-user-id', payload.userId);
    requestHeaders.set('x-user-email', payload.email);

    return NextResponse.next({
      request: {
        headers: requestHeaders,
      },
    });
  } catch (error) {
    // Log error server-side but return generic message
    console.error('Token verification error:', error);
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401, headers: response.headers }
    );
  }
}
